import sys
from collections import deque

s = sys.stdin.readline().strip()
n = len(s)

def balanced(t):
    b = 0
    for c in t:
        b += 1 if c == '[' else -1
        if b < 0:
            return False
    return b == 0

if n <= 12:
    # breadth-first search over every string reachable by swapping two characters
    dist = {s: 0}
    q = deque([s])
    ans = None
    while q:
        t = q.popleft()
        if balanced(t):
            ans = dist[t]
            break
        arr = list(t)
        for i in range(n):
            for j in range(i + 1, n):
                if arr[i] != arr[j]:
                    arr[i], arr[j] = arr[j], arr[i]
                    u = ''.join(arr)
                    arr[i], arr[j] = arr[j], arr[i]
                    if u not in dist:
                        dist[u] = dist[t] + 1
                        q.append(u)
    print(ans)
else:
    # simulate: repeatedly swap the first unmatched ']' with the last '['
    arr = list(s)
    swaps = 0
    while True:
        b = 0
        bad = -1
        for idx, c in enumerate(arr):
            b += 1 if c == '[' else -1
            if b < 0:
                bad = idx
                break
        if bad == -1:
            break
        j = n - 1
        while arr[j] != '[':
            j -= 1
        arr[bad], arr[j] = arr[j], arr[bad]
        swaps += 1
    print(swaps)

